// ═══════════════════════════════════════════════════════
// Filtra contatos que não existem no Trello (sem duplicados)
// ═══════════════════════════════════════════════════════

// 1. Obter todos os contatos retornados pela Evolution API
const contactsItems = $('Obter Contatos Evolution').all();

// 2. Obter todos os cards retornados do Trello
const trelloItems = $('Obter Cards Trello').all();

const existingCards = trelloItems.map(item => ({
  name: (item.json.name || '').toLowerCase(),
  desc: (item.json.desc || '').toLowerCase()
}));

const newLeads = [];

for (const contact of contactsItems) {
  const rawJid = contact.json.remoteJid || '';
  if (contact.json.isGroup === true || !rawJid) continue;

  // Extrai o número de telefone (limpo)
  const phone = rawJid.split('@')[0];
  const pushName = (contact.json.pushName || '').trim();

  // Verifica se o número já existe no Trello (no título ou descrição)
  const alreadyExists = existingCards.some(card => 
    card.name.includes(phone) || card.desc.includes(phone)
  );

  if (!alreadyExists) {
    const displayName = pushName || 'Desconhecido';
    const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

    newLeads.push({
      json: {
        phone,
        pushName: displayName,
        cardTitle: pushName ? `${pushName} (${phone})` : `Lead ${phone}`,
        cardDescription: 
          `📲 Lead importador historicamente via WhatsApp\n` +
          `Fonte: Evolution API (Histórico)\n\n` +
          `Nome: ${displayName}\n` +
          `Número: ${phone}\n` +
          `Importado em: ${now}`
      }
    });
  }
}

return newLeads;
